use novel_storage::*;
use serde_json::{json,Value};
use sqlx::Connection;
fn scene(text:&str)->Scene{Scene{schema_version:1,title:format!("Draft {text}"),document:json!({"type":"doc","content":[{"type":"paragraph","attrs":{"dir":"rtl","lang":"ar","lineSpacing":1.5},"content":[{"type":"text","text":text,"marks":[{"type":"bold"},{"type":"underline"}]}]}]})}}
fn planning(value:&str)->Value{json!({"schemaVersion":1,"fields":[],"records":[{"id":"character","kind":"character","name":"يس 中文","aliases":[],"notes":value,"values":{},"links":[]}],"plotPoints":[],"facts":[],"boards":[],"lanes":[],"events":[],"constraints":[],"issues":[]})}
async fn setup()->(tempfile::TempDir,Storage,String,String,SceneRecord){let d=tempfile::tempdir().unwrap();let s=Storage::open(&d.path().join("test.sqlite")).await.unwrap();let p=s.create_project("Past project").await.unwrap();let c=s.create_chapter(&p.id,"Past chapter").await.unwrap();let a=s.create_scene(&c.id,scene("يس مِ 👩🏽‍🚀 中文 \u{e000}")).await.unwrap();(d,s,p.id,c.id,a)}
async fn point_id(s:&Storage,sequence:i64)->String{s.changes(sequence.saturating_sub(1),1).await.unwrap().into_iter().find(|revision|revision.sequence==sequence).map(|revision|revision.id).unwrap_or_default()}
fn object<'a>(p:&'a ProjectTimePreview,entity:&str,kind:&str)->&'a TimeMachineObject{p.objects.iter().find(|object|object.entity_id==entity&&object.entity_type==kind).unwrap()}
#[tokio::test]
async fn same_cutoff_projects_titles_orders_manuscript_and_story_bible_then_recovers_selected_pieces(){
 let (_d,s,pid,cid,a)=setup().await;let c2=s.create_chapter(&pid,"Later chapter").await.unwrap();let b=s.create_scene(&cid,scene("Second 中文")).await.unwrap();
 let plan1=s.save_project_data(&pid,"planning",planning("Old notes مِ"),None).await.unwrap();let old=s.sync_cursor().await.unwrap();
 s.rename_project(&pid,"New project").await.unwrap();s.rename_chapter(&cid,"New chapter").await.unwrap();s.reorder_chapters(&pid,vec![c2.id.clone(),cid.clone()]).await.unwrap();s.reorder_scenes(&cid,vec![b.id.clone(),a.id.clone()]).await.unwrap();s.move_scene(&a.id,&c2.id,0).await.unwrap();
 let latest=s.save_scene(&a.id,scene("New text"),Some(a.revision_id.clone())).await.unwrap();let plan2=s.save_project_data(&pid,"planning",planning("New notes"),Some(plan1.revision_id.clone())).await.unwrap();
 let before=s.project_time_preview(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await).await.unwrap();assert_eq!(object(&before,&pid,"project").heads[0].title.as_deref(),Some("Past project"));assert_eq!(object(&before,&cid,"chapter").heads[0].title.as_deref(),Some("Past chapter"));assert_eq!(object(&before,&cid,"chapter").position,Some(0));
 assert_eq!((object(&before,&a.id,"scene").chapter_id.as_deref(),object(&before,&a.id,"scene").position),(Some(cid.as_str()),Some(0)));assert_eq!(object(&before,&b.id,"scene").position,Some(1));assert_eq!(object(&before,&format!("{pid}:planning"),"projectData").heads[0].revision_id,plan1.revision_id);
 let now=s.sync_cursor().await.unwrap();let after=s.project_time_preview(&pid,&now.epoch,now.sequence,&point_id(&s,now.sequence).await).await.unwrap();assert_eq!(object(&after,&cid,"chapter").position,Some(1));assert_eq!(object(&after,&a.id,"scene").chapter_id.as_deref(),Some(c2.id.as_str()));assert_eq!(object(&after,&b.id,"scene").position,Some(0));
 let recovered=s.recover_time_piece(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await,&a.id,"scene",&a.revision_id,vec![latest.revision_id.clone()]).await.unwrap();assert_eq!(recovered.payload,serde_json::to_value(&a.scene).unwrap());assert_ne!(recovered.id,a.revision_id);assert_eq!(recovered.parents,vec![latest.revision_id]);assert_eq!(s.load_scene(&b.id).await.unwrap().revision_id,b.revision_id);
 let plan=s.recover_time_piece(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await,&format!("{pid}:planning"),"projectData",&plan1.revision_id,vec![plan2.revision_id.clone()]).await.unwrap();assert_eq!(plan.payload,plan1.payload);assert_eq!(plan.parents,vec![plan2.revision_id]);assert_eq!(s.load_project_data(&pid,"planning").await.unwrap().unwrap().revision_id,plan.id);
 assert_eq!(s.open_project(&pid).await.unwrap().project.title,"New project");assert_eq!(s.load_project_scene(&pid,&a.id).await.unwrap().chapter_id,c2.id);
 let frozen=s.project_time_preview(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await).await.unwrap();assert_eq!(object(&frozen,&a.id,"scene").heads,object(&before,&a.id,"scene").heads);assert_eq!(object(&frozen,&a.id,"scene").current_head_ids,vec![recovered.id]);
}
#[tokio::test]
async fn deletion_boundaries_revival_stale_heads_and_competing_versions_never_overwrite(){
 let(d,s,pid,_cid,a)=setup().await;let old=s.sync_cursor().await.unwrap();let deleted=s.delete_scene(&a.id,&a.revision_id).await.unwrap();let cut=s.sync_cursor().await.unwrap();
 let before=s.project_time_preview(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await).await.unwrap();assert_eq!(object(&before,&a.id,"scene").heads[0].entity_type,"scene");let at=s.project_time_preview(&pid,&cut.epoch,cut.sequence,&point_id(&s,cut.sequence).await).await.unwrap();assert_eq!(object(&at,&a.id,"scene").heads[0].entity_type,"tombstone");
 assert!(s.recover_time_piece(&pid,&cut.epoch,cut.sequence,&point_id(&s,cut.sequence).await,&a.id,"scene",&deleted,vec![deleted.clone()]).await.is_err());
 let restored=s.recover_time_piece(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await,&a.id,"scene",&a.revision_id,vec![deleted.clone()]).await.unwrap();assert_eq!(restored.parents,vec![deleted]);assert_eq!(s.load_project_scene(&pid,&a.id).await.unwrap().scene,a.scene);
 let other=Storage::open(&d.path().join("test.sqlite")).await.unwrap();let concurrent=other.save_scene(&a.id,scene("Other window"),Some(restored.id.clone())).await.unwrap();let count=s.history(&a.id).await.unwrap().len();assert!(s.recover_time_piece(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await,&a.id,"scene",&a.revision_id,vec![restored.id]).await.unwrap_err().starts_with("Conflict"));assert_eq!(s.history(&a.id).await.unwrap().len(),count);assert_eq!(s.load_scene(&a.id).await.unwrap(),concurrent);
 s.preserve_conflict(&a.id,scene("Competing branch"),&a.revision_id).await.unwrap();let heads=s.scene_heads(&a.id).await.unwrap().revision_ids;assert_eq!(heads.len(),2);assert!(s.recover_time_piece(&pid,&old.epoch,old.sequence,&point_id(&s,old.sequence).await,&a.id,"scene",&a.revision_id,heads).await.unwrap_err().starts_with("Conflict"));
 let current=s.sync_cursor().await.unwrap();let preview=s.project_time_preview(&pid,&current.epoch,current.sequence,&point_id(&s,current.sequence).await).await.unwrap();assert_eq!(object(&preview,&a.id,"scene").heads.len(),2);assert!(preview.warnings.iter().any(|warning|warning.contains("competing")));
}
#[tokio::test]
async fn recorded_sequence_not_foreign_timestamp_defines_cutoff_and_epochs_are_checked(){
 let(_d,a,pid,_cid,sc)=setup().await;let d=tempfile::tempdir().unwrap();let b=Storage::open(&d.path().join("replica.sqlite")).await.unwrap();let remote=a.sync_cursor().await.unwrap();let local=b.sync_cursor().await.unwrap();let manifest=a.sync_manifest(&pid).await.unwrap();let page=a.pull_revisions(&pid,SyncCursor{epoch:remote.epoch.clone(),sequence:0},100).await.unwrap();b.ingest_revisions(&pid,&local.epoch,&remote.epoch,manifest,page.revisions).await.unwrap();let before=b.sync_cursor().await.unwrap();
 let saved=a.save_scene(&sc.id,scene("Late arrival"),Some(sc.revision_id.clone())).await.unwrap();let mut revisions=a.pull_revisions(&pid,SyncCursor{epoch:remote.epoch.clone(),sequence:remote.sequence},100).await.unwrap().revisions;revisions[0].created_at="1900-01-01T00:00:00.000Z".into();b.ingest_revisions(&pid,&local.epoch,&remote.epoch,a.sync_manifest(&pid).await.unwrap(),revisions).await.unwrap();
 let points=b.project_time_points(&pid,None,100).await.unwrap();assert_eq!(points.points[0].revision_id,saved.revision_id);assert_eq!(points.points[0].created_at,"1900-01-01T00:00:00.000Z");assert!(points.points[0].sequence>before.sequence);
 let frozen=b.project_time_preview(&pid,&before.epoch,before.sequence,&point_id(&b,before.sequence).await).await.unwrap();assert_eq!(object(&frozen,&sc.id,"scene").heads[0].revision_id,sc.revision_id);
 assert!(b.project_time_preview(&pid,&remote.epoch,before.sequence,&point_id(&b,before.sequence).await).await.is_err());assert!(b.project_time_preview(&pid,&before.epoch,points.points[0].sequence+1,&point_id(&b,points.points[0].sequence+1).await).await.is_err());assert!(b.recover_time_piece(&pid,&before.epoch,before.sequence,&point_id(&b,before.sequence).await,&sc.id,"scene",&saved.revision_id,vec![saved.revision_id.clone()]).await.is_err());
 b.rotate_epoch().await.unwrap();assert!(b.project_time_preview(&pid,&before.epoch,before.sequence,&point_id(&b,before.sequence).await).await.is_err());
}
#[tokio::test]
async fn pagination_project_ownership_and_injected_marker_failure_are_bounded_and_atomic(){
 let(d,s,pid,cid,a)=setup().await;let cutoff=s.sync_cursor().await.unwrap();let page=s.project_time_points(&pid,None,2).await.unwrap();assert!(page.has_more);assert_eq!(page.points.len(),2);let second=s.project_time_points(&pid,Some(page.points[1].sequence),100).await.unwrap();assert!(second.points.iter().all(|point|point.sequence<page.points[1].sequence));assert!(s.project_time_points(&pid,None,101).await.is_err());assert!(s.project_time_points(&pid,Some(0),1).await.is_err());
 let foreign=s.create_project("Foreign").await.unwrap();assert!(s.project_time_preview(&foreign.id,&cutoff.epoch,cutoff.sequence,&point_id(&s,cutoff.sequence).await).await.is_err());let other=s.create_scene(&cid,scene("Other")).await.unwrap();assert!(s.recover_time_piece(&pid,&cutoff.epoch,cutoff.sequence,&point_id(&s,cutoff.sequence).await,&other.id,"scene",&a.revision_id,vec![other.revision_id]).await.is_err());
 let mut raw=sqlx::SqliteConnection::connect_with(&sqlx::sqlite::SqliteConnectOptions::new().filename(d.path().join("test.sqlite"))).await.unwrap();sqlx::query("CREATE TRIGGER fail_recovery_marker BEFORE INSERT ON change_marker BEGIN SELECT RAISE(ABORT,'synthetic marker failure'); END").execute(&mut raw).await.unwrap();let before=s.sync_cursor().await.unwrap();let count=s.history(&a.id).await.unwrap().len();assert!(s.recover_time_piece(&pid,&cutoff.epoch,cutoff.sequence,&point_id(&s,cutoff.sequence).await,&a.id,"scene",&a.revision_id,vec![a.revision_id.clone()]).await.is_err());assert_eq!(s.load_scene(&a.id).await.unwrap().revision_id,a.revision_id);assert_eq!(s.history(&a.id).await.unwrap().len(),count);assert_eq!(s.sync_cursor().await.unwrap(),before);
 sqlx::query("DROP TRIGGER fail_recovery_marker").execute(&mut raw).await.unwrap();sqlx::query("DROP TRIGGER immutable_revision_update").execute(&mut raw).await.unwrap();sqlx::query("UPDATE revision_envelope SET checksum='corrupt' WHERE id=?").bind(&a.revision_id).execute(&mut raw).await.unwrap();assert!(s.recover_time_piece(&pid,&cutoff.epoch,cutoff.sequence,&point_id(&s,cutoff.sequence).await,&a.id,"scene",&a.revision_id,vec![a.revision_id.clone()]).await.unwrap_err().contains("checksum"));assert_eq!(s.sync_cursor().await.unwrap(),before);
}
#[tokio::test]
async fn portable_archive_remaps_new_reveal_knowledge_scene_refs_but_preserves_exact_snapshots(){
 let(_d,s,pid,_cid,a)=setup().await;let mut doc=planning("Exact notes مِ Chinese 中文");doc["facts"]=json!([{"id":"fact","subjectId":"character","property":"home","value":"Withdrawn new value","status":"proposal","confirmed":false,"observerId":null,"source":"author","eventId":null,"untilEventId":null}]);doc["readerReveals"]=json!([{"id":"reveal","eventId":null,"factId":"fact","scene":{"kind":"scene","id":a.id},"position":0,"notes":"Exact reveal مِ 中文"}]);doc["knowledge"]=json!([{"id":"knowledge","characterId":"character","factId":"fact","stance":"knows","factSnapshot":{"subjectId":"character","property":"home","value":"Old approved value يس 中文"},"interpretation":"Exact interpretation مِ 👩🏽‍🚀","source":"explicit author","scope":{"kind":"scenes","sceneIds":[a.id]}}]);
 // Author the knowledge while its source is approved, then change canon. The
 // archive must preserve the legitimate stale snapshot, not fabricate a new
 // "knows" claim against an already withdrawn proposal.
 let mut approved=doc.clone();approved["facts"][0]["value"]=doc["knowledge"][0]["factSnapshot"]["value"].clone();approved["facts"][0]["status"]=json!("fact");approved["facts"][0]["confirmed"]=json!(true);let seed=s.save_project_data(&pid,"planning",approved,None).await.unwrap();s.save_project_data(&pid,"planning",doc.clone(),Some(seed.revision_id)).await.unwrap();
 let imported=s.import_archive(&s.export_archive(&pid).await.unwrap()).await.unwrap();let copied=s.load_project_data(&imported.project.id,"planning").await.unwrap().unwrap().payload;assert_ne!(imported.scenes[0].id,a.id);assert_eq!(copied["readerReveals"][0]["scene"]["id"],imported.scenes[0].id);assert_eq!(copied["knowledge"][0]["scope"]["sceneIds"][0],imported.scenes[0].id);assert_eq!(copied["knowledge"][0]["factSnapshot"],doc["knowledge"][0]["factSnapshot"]);assert_eq!(copied["knowledge"][0]["interpretation"],doc["knowledge"][0]["interpretation"]);assert_eq!(copied["readerReveals"][0]["notes"],doc["readerReveals"][0]["notes"]);assert_eq!(copied["records"],doc["records"]);assert_eq!(copied["facts"],doc["facts"]);assert_eq!(s.load_project_data(&pid,"planning").await.unwrap().unwrap().payload,doc);
}
#[tokio::test]
async fn older_same_epoch_backup_reusing_sequence_cannot_reinterpret_a_selected_point(){
 let(d,s,pid,_cid,a)=setup().await;let path=d.path().join("before.sqlite");s.backup(&path).await.unwrap();let saved=s.save_scene(&a.id,scene("Lost from older backup"),Some(a.revision_id.clone())).await.unwrap();let cut=s.sync_cursor().await.unwrap();let restored=Storage::open(&path).await.unwrap();let replacement=restored.save_scene(&a.id,scene("New branch after older restore"),Some(a.revision_id)).await.unwrap();assert_eq!(restored.sync_cursor().await.unwrap(),cut);
 assert!(restored.project_time_preview(&pid,&cut.epoch,cut.sequence,&saved.revision_id).await.unwrap_err().contains("unavailable"));assert!(restored.project_time_preview(&pid,&cut.epoch,cut.sequence,&replacement.revision_id).await.is_ok());assert!(restored.recover_time_piece(&pid,&cut.epoch,cut.sequence,&saved.revision_id,&a.id,"scene",&replacement.revision_id,vec![replacement.revision_id.clone()]).await.is_err());assert_eq!(restored.load_scene(&a.id).await.unwrap().revision_id,replacement.revision_id);
}
#[tokio::test]
async fn unresolved_metadata_branches_remain_visible_without_arbitrary_hierarchy_selection(){
 let(_d,a,pid,cid,sc)=setup().await;let d=tempfile::tempdir().unwrap();let b=Storage::open(&d.path().join("second.sqlite")).await.unwrap();let remote=a.sync_cursor().await.unwrap();let local=b.sync_cursor().await.unwrap();b.ingest_revisions(&pid,&local.epoch,&remote.epoch,a.sync_manifest(&pid).await.unwrap(),a.pull_revisions(&pid,SyncCursor{epoch:remote.epoch.clone(),sequence:0},100).await.unwrap().revisions).await.unwrap();a.rename_chapter(&cid,"Writer A title").await.unwrap();b.rename_chapter(&cid,"Writer B title").await.unwrap();let b_epoch=b.sync_cursor().await.unwrap().epoch;
 let competing=b.pull_revisions(&pid,SyncCursor{epoch:b_epoch.clone(),sequence:remote.sequence},100).await.unwrap().revisions;a.ingest_revisions(&pid,&remote.epoch,&b_epoch,b.sync_manifest(&pid).await.unwrap(),competing).await.unwrap();let current=a.sync_cursor().await.unwrap();let preview=a.project_time_preview(&pid,&current.epoch,current.sequence,&point_id(&a,current.sequence).await).await.unwrap();let chapter=object(&preview,&cid,"chapter");assert_eq!(chapter.heads.len(),2);assert!(chapter.heads.iter().any(|head|head.title.as_deref()==Some("Writer A title")));assert!(chapter.heads.iter().any(|head|head.title.as_deref()==Some("Writer B title")));assert!(object(&preview,&sc.id,"scene").chapter_id.is_none());
}
#[tokio::test]
async fn legacy_missing_initial_placement_is_not_fabricated_from_current_mutable_rows(){
 let d=tempfile::tempdir().unwrap();let s=Storage::open(&d.path().join("legacy.sqlite")).await.unwrap();let saved=s.save(scene("Legacy محفوظ"),None).await.unwrap();let cut=s.sync_cursor().await.unwrap();let preview=s.project_time_preview("prototype-project",&cut.epoch,cut.sequence,&saved.revision_id).await.unwrap();let sc=object(&preview,"prototype-scene","scene");assert_eq!(sc.chapter_id,None);assert_eq!(sc.position,None);assert!(preview.warnings.iter().any(|warning|warning.contains("missing early metadata")));
}
